package cn.zhuatech.qms.deep;import cn.zhuatech.qms.common.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/quality-ops") @PreAuthorize("hasRole('ADMIN')") public class DeepQualityAdminController{private final DeepQualityService s;public DeepQualityAdminController(DeepQualityService x){s=x;}@PostMapping("/plans")ApiResponse<?> plan(@RequestBody DeepQualityService.PlanInput x){return ApiResponse.ok(s.createPlan(x));}@PostMapping("/plans/{id}/activate")ApiResponse<?> activate(@PathVariable Long id){return ApiResponse.ok(s.activatePlan(id));}@PostMapping("/capas/{id}/verify")ApiResponse<?> verify(@PathVariable Long id,@RequestBody DeepQualityService.VerifyInput x){return ApiResponse.ok(s.verifyCapa(id,x));}}
